import{z as s,x as d,o as t,c as B,q as l,j as A,D as e,d as r,s as o,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"多束电子束直写","description":"","frontmatter":{"title":"多束电子束直写","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/multibeam-direct-write.md","filePath":"litho/multibeam-direct-write.md","lastUpdated":1791413859000}'),p={name:"litho/multibeam-direct-write.md"};function h(m,a,D,u,F,c){const i=d("Mermaid");return t(),B("div",null,[a[2]||(a[2]=l('<h1 id="多束电子束直写" tabindex="-1">多束电子束直写 <a class="header-anchor" href="#多束电子束直写" aria-label="Permalink to &quot;多束电子束直写&quot;">​</a></h1><div class="epigraph"><p>掩模多束已经量产；晶圆直写仍撞面积×剂量墙。无掩模对逻辑全片是另一道产能物理，不是把写版机放大。</p><footer>—— 对照 MAPPER/IMS 一类晶圆多束直写尝试与掩模多束成功的公开对照</footer></div><p><a href="/litho/3d-nand-litho-shift">上一课</a>结束节点经济课序。缺口是：能否绕过掩模。本课钉多束电子束直写（晶圆）。干涉光刻作为周期图形的另一条路，留给<a href="/litho/interference-lithography">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/multibeam-mask-writer">多束写掩模</a> 成功，因为 6 寸版面积有限、一张版服务许多晶圆。晶圆直写要把每片都写满，面积大两到三个数量级，即使十万束，wph 仍难跟扫描机比。MAPPER 等项目展示过原理与部分产线故事，量产逻辑全片未取代光学。用途残留：研制、小批量、个性化、修补、对准标记、某些封装。</p><p><span class="marginnote">术语翻译：无掩模直写就是「不用版子，让电子束直接在晶圆胶上画画」。省掉掩模成本与制作周期，但每一片都得从头画一遍；掩模路线是「画一次版、印几万片」，直写是「每片都画一次」，这正是两者的产能分水岭。</span></p><p>缺口是<strong>面积墙</strong>，不是束斑能不能细。把掩模多束的成功直接写成晶圆无掩模量产，单位错了。</p><h3 id="与-pec-的关系" tabindex="-1">与 PEC 的关系 <a class="header-anchor" href="#与-pec-的关系" aria-label="Permalink to &quot;与 PEC 的关系&quot;">​</a></h3><p>晶圆直写仍要电子 PEC，邻近核与衬底有关，和光学 OPC 不同。混合流程（光学粗 + 电子修）是可能工程，不是本课重点。</p><p><span class="marginnote">无掩模的价值在掩模成本摊不薄的时候（样品、多品种），与交叉课的「量大摊销」相反。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>比较：写时间 ∝ 面积 × 剂量 / 总电流。扫描机：一场光学并行。只有当品种极多、面积极小或分辨率光学达不到时，直写胜。规划不要用直写去填 EUV 槽位缺口——量级不对。</p><p><span class="marginnote">数字实例：一张 6 寸掩模版约 0.02 平方米，一片 300 mm 晶圆约 0.07 平方米，单张只差三倍多；但版写一次就能印几万片，直写每片都重画——累计要「画」的面积差上两三个数量级，这就是面积墙的算术。</span></p>',13)),(t(),A(n,null,{default:e(()=>[o(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEED%5B%22%E8%A6%81%E5%9B%BE%E5%BD%A2%E5%8C%96%22%5D%20--%3E%20Q1%7B%22%E5%93%81%E7%A7%8D%E5%A4%9A%20%E6%89%B9%E9%87%8F%E5%B0%8F%3F%22%7D%0A%20%20Q1%20--%20%22%E6%98%AF%22%20--%3E%20DW%5B%22%E7%9B%B4%E5%86%99%E8%83%9C%20%E6%97%A0%E6%8E%A9%E6%A8%A1%E6%88%90%E6%9C%AC%22%5D%0A%20%20NEED%20--%3E%20Q2%7B%22%E5%85%89%E5%AD%A6%E5%88%86%E8%BE%A8%E7%8E%87%E4%B8%8D%E5%A4%9F%3F%22%7D%0A%20%20Q2%20--%20%22%E6%98%AF%22%20--%3E%20DW2%5B%22%E7%94%B5%E5%AD%90%E6%9D%9F%E7%9B%B4%E5%86%99%E8%A1%A5%E4%BD%8D%22%5D%0A%20%20NEED%20--%3E%20Q3%7B%22%E9%80%BB%E8%BE%91%E5%85%A8%E7%89%87%E9%87%8F%E4%BA%A7%3F%22%7D%0A%20%20Q3%20--%20%22%E6%98%AF%22%20--%3E%20OPT%5B%22%E5%85%89%E5%AD%A6%E6%8A%95%E5%BD%B1%20%E5%B9%B6%E8%A1%8C%E4%B8%80%E5%9C%BA%22%5D%0A%20%20DW%20--%3E%20WPH%7B%22wph%20%E5%A4%9F%E4%BA%A7%E7%BA%BF%3F%22%7D%0A%20%20DW2%20--%3E%20WPH%0A%20%20WPH%20--%20%22%E5%90%A6%22%20--%3E%20NICHE%5B%22%E9%80%80%E5%9B%9E%E7%A0%94%E5%88%B6%20%2F%20%E4%BF%AE%E8%A1%A5%20%2F%20%E5%B0%8F%E6%89%B9%E9%87%8F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"光学投影一次性把掩模场印到晶圆；直写是串行（尽管多束并行度高）。并行度必须赶上场像素数才有同等 wph，这正是掩模多束够用、晶圆不够的原因。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：光学扫描机像把整张幻灯片一次投影满场；直写像用几万支同时落笔的针尖一笔一笔描。一个曝光场有几百万个像素位，针尖数比像素数还少几个数量级，描完的时间自然追不上「闪」一下的投影。")],-1)),(t(),A(n,null,{default:e(()=>[o(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20MASK%5B%22%E6%8E%A9%E6%A8%A1%E5%A4%9A%E6%9D%9F%3A%20%E9%9D%A2%E7%A7%AF%E5%B0%8F%22%5D%20--%3E%20OK%5B%22%E9%87%8F%E4%BA%A7%E5%86%99%E7%89%88%22%5D%0A%20%20WAF%5B%22%E6%99%B6%E5%9C%86%E7%9B%B4%E5%86%99%3A%20%E9%9D%A2%E7%A7%AF%E5%A4%A7%22%5D%20--%3E%20WALL%5B%22wph%20%E5%A2%99%22%5D%0A%20%20WALL%20--%3E%20NICHE%5B%22%E6%A0%B7%E5%93%81%20%2F%20%E5%B0%8F%E6%89%B9%E9%87%8F%20%2F%20%E4%BF%AE%E8%A1%A5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不宣布直写永远失败。源电流与胶灵敏度的未来改善可能移动墙，仍须过面积算术。不写某已停项目的内部规格。</p><p>后课默认：全片无掩模电子束不是先进逻辑的主路径；下一课干涉法用光子的并行性印周期结构。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>晶圆多束直写撞面积×剂量墙；掩模多束因面积小而量产。</li><li>适合小批量与研制，不适合填 EUV 产能缺口。</li><li>并行度必须比上场像素数。</li><li>出处：晶圆多束直写与掩模多束的公开对照。</li></ul>',5))])}const _=s(p,[["render",h]]);export{P as __pageData,_ as default};
